double bounded(PyObject*value,double low,double high){const auto v=p::scalar(value);if(v<low||v>high)throw p::Error("Detached turret number outside wire envelope");return v;}
std::int64_t integer(PyObject*value,std::int64_t low=0){const auto n=p::wide(value);if(n<low||n>2147483647)throw p::Error("Detached turret integer outside wire envelope");return n;}
Point vector(PyObject*value,double bound){auto result=p::numbers<3>(value);for(auto v:result)if(std::abs(v)>bound)throw p::Error("Detached turret vector outside wire envelope");return result;}
Point point(PyObject*object,const char*name,double bound){auto value=p::value(object,name);return vector(value.get(),bound);}
Point nativePoint(PyObject*object){if(PyTuple_Check(object)||PyList_Check(object))return p::numbers<3>(object);Point result;for(unsigned i=0;i<3;++i){auto v=p::value(object,i==0?"x":i==1?"y":"z");result[i]=p::scalar(v.get());}return result;}
bool bit(PyObject*object,const char*name){auto value=p::value(object,name);if(!PyBool_Check(value.get()))throw p::Error("Detached turret boolean is invalid");return value.get()==Py_True;}
Owner owner(const std::string&kind,std::int64_t id){if(kind!="bot"&&kind!="player")throw p::Error("Detached turret actor kind is invalid");return {kind=="player",id};}
Owner actorKey(const std::string&key){const auto split=key.find(':');if(split==std::string::npos||key.find(':',split+1)!=std::string::npos)throw p::Error("Detached turret actor key is invalid");std::size_t used=0;const auto suffix=key.substr(split+1);const auto id=std::stoll(suffix,&used);if(used!=suffix.size()||id<1||id>2147483647)throw p::Error("Detached turret actor id is invalid");return owner(key.substr(0,split),id);}
std::string actorKey(Owner key){return std::string(key.human?"player:":"bot:")+std::to_string(key.id);}
Checkpoint checkpoint(PyObject*row){if(p::size(row)!=8)throw p::Error("Detached turret checkpoint width is invalid");Checkpoint out;auto name=p::item(row,0),seq=p::item(row,1);out.player=actorKey(p::string(name.get()));out.sequence=integer(seq.get(),1);for(unsigned i=0;i<6;++i){auto item=p::item(row,i+2);(i<3?out.linear[i]:out.angular[i-3])=bounded(item.get(),-1.e12,1.e12);}return out;}
std::vector<Checkpoint> checkpoints(PyObject*rows){if(p::size(rows)>30)throw p::Error("Detached turret checkpoint list is too large");std::vector<Checkpoint> out;std::set<Owner> unique;for(Py_ssize_t i=0;i<p::size(rows);++i){auto row=p::item(rows,i);auto result=checkpoint(row.get());if(!unique.insert(result.player).second)throw p::Error("Detached turret checkpoint actor is repeated");out.push_back(result);}return out;}
Frame frame(PyObject*object){if(!PyDict_Check(object))throw p::Error("Detached turret body is invalid");Frame out;out.position=point(object,"position",5000.);out.attitude=point(object,"attitude",1000.);out.centre=point(object,"centre",5000.);out.velocity=point(object,"velocity",3000.);out.angular_velocity=point(object,"angular_velocity",1000.);out.grounded=bit(object,"grounded");out.sleeping=bit(object,"sleeping");auto serial=p::value(object,"impact_serial"),acks=p::value(object,"acks"),impact=p::value(object,"impact");out.impact_serial=integer(serial.get());out.acknowledgements=checkpoints(acks.get());if(impact.get()!=Py_None){Impact hit;hit.point=point(impact.get(),"point",5000.);hit.normal=point(impact.get(),"normal",1.);hit.velocity=point(impact.get(),"velocity",3000.);auto energy=p::value(impact.get(),"energy");hit.energy=bounded(energy.get(),0.,13500000.);out.impact=hit;}return out;}
// Stock getBoundingBox returns (minimum, maximum, radius). The original
// component_bounds consumer reads the first two entries only.
stock_native_bot_turret::Component componentBounds(PyObject*object){stock_native_bot_turret::Component out;auto tester=p::value(object,"hitTester"),bounds=p::value(tester.get(),"bbox");if(p::size(bounds.get())<2)throw p::Error("Detached turret component bounds are unavailable");auto low=p::item(bounds.get(),0),high=p::item(bounds.get(),1);out.bounds.minimum=nativePoint(low.get());out.bounds.maximum=nativePoint(high.get());for(unsigned i=0;i<3;++i)if(out.bounds.minimum[i]>=out.bounds.maximum[i])throw p::Error("Detached turret component bounds are empty");return out;}
stock_native_bot_turret::Component component(PyObject*object){auto tester=p::value(object,"hitTester"),hit=p::value(tester.get(),"localHitTest");if(!PyCallable_Check(hit.get()))throw p::Error("Detached turret component tester is unavailable");return componentBounds(object);}
p::Ref packedCheckpoint(const Checkpoint&c){auto out=p::list();p::append(out.get(),p::text(actorKey(c.player)));p::append(out.get(),p::integer(c.sequence));for(auto v:c.linear)p::append(out.get(),p::number(v));for(auto v:c.angular)p::append(out.get(),p::number(v));return out;}
p::Ref packedFrame(const Frame&f){auto out=p::dict();p::set(out.get(),"position",p::numbers(f.position));p::set(out.get(),"attitude",p::numbers(f.attitude));p::set(out.get(),"centre",p::numbers(f.centre));p::set(out.get(),"velocity",p::numbers(f.velocity));p::set(out.get(),"angular_velocity",p::numbers(f.angular_velocity));p::set(out.get(),"grounded",p::boolean(f.grounded));p::set(out.get(),"sleeping",p::boolean(f.sleeping));p::set(out.get(),"impact_serial",p::integer(f.impact_serial));auto acks=p::list();for(const auto&c:f.acknowledgements)p::append(acks.get(),packedCheckpoint(c));p::set(out.get(),"acks",acks);auto impact=f.impact?p::dict():p::retain(Py_None);if(f.impact){p::set(impact.get(),"point",p::numbers(f.impact->point));p::set(impact.get(),"normal",p::numbers(f.impact->normal));p::set(impact.get(),"velocity",p::numbers(f.impact->velocity));p::set(impact.get(),"energy",p::number(f.impact->energy));}p::set(out.get(),"impact",impact);return out;}
