bool readRow(PyObject*object,Row&output){try{Row out;auto kind=p::value(object,"actor_kind"),id=p::value(object,"actor_id"),created=p::value(object,"created_time_ms"),sequence=p::value(object,"motion_seq"),flight=p::value(object,"flight");out.owner=owner(p::string(kind.get()),integer(id.get(),1));out.created_time_ms=integer(created.get());out.attitude=point(object,"attitude",1000.);out.spin=point(object,"spin",1000.);if(sequence.get()!=Py_None){out.motion_sequence=integer(sequence.get(),1);auto time=p::value(object,"motion_time_ms"),support=p::value(object,"support_key");out.motion_time_ms=integer(time.get());if(support.get()!=Py_None)out.support=actorKey(p::string(support.get()));}
    auto&f=out.flight;f.origin=point(flight.get(),"origin",5000.);f.velocity=point(flight.get(),"velocity",3000.);f.rest=point(flight.get(),"rest",5000.);f.impact_velocity=point(flight.get(),"impact_velocity",3000.);auto duration=p::value(flight.get(),"duration"),energy=p::value(flight.get(),"energy"),contact=p::value(flight.get(),"contact"),segments=p::value(flight.get(),"segments"),rest_attitude=p::value(flight.get(),"rest_attitude"),body=p::value(flight.get(),"body");f.duration=bounded(duration.get(),0.,8.);f.energy=bounded(energy.get(),0.,13500000.);f.landed=bit(flight.get(),"landed");if(contact.get()!=Py_None)f.contact=vector(contact.get(),5000.);if(f.landed!=bool(f.contact))throw p::Error("Detached turret landing outcome is invalid");if(rest_attitude.get()!=Py_None)f.rest_attitude=vector(rest_attitude.get(),1000.);if(PyDict_Check(flight.get())&&PyDict_GetItemString(flight.get(),"body"))f.body=frame(body.get());const auto count=p::size(segments.get());if(count<1||count>4)throw p::Error("Detached turret segment count is invalid");for(Py_ssize_t i=0;i<count;++i){auto raw=p::item(segments.get(),i),start=p::value(raw.get(),"start"),length=p::value(raw.get(),"duration");Segment segment;segment.origin=point(raw.get(),"origin",5000.);segment.velocity=point(raw.get(),"velocity",3000.);segment.start=bounded(start.get(),0.,8.);segment.duration=bounded(length.get(),0.,8.);if(segment.start+segment.duration>8.+1.e-9)throw p::Error("Detached turret segment exceeds flight window");f.segments.push_back(segment);}output=std::move(out);return true;}catch(const std::exception&e){if(!PyErr_Occurred())PyErr_SetString(PyExc_ValueError,e.what());return false;}}
bool readComponents(PyObject*descriptor,std::vector<Component>&output){try{auto turret=p::value(descriptor,"turret"),gun=p::value(descriptor,"gun"),mount=p::value(turret.get(),"gunPosition");std::vector<Component> out;for(auto*object:{turret.get(),gun.get()}){Component part;part.geometry=component(object);auto weight=p::value(object,"weight");part.mass=p::scalar(weight.get());if(part.mass<=0.)throw p::Error("Detached component weight must be positive");out.push_back(part);}out[1].geometry.offset=nativePoint(mount.get());properties(out);output=std::move(out);return true;}catch(const std::exception&e){if(!PyErr_Occurred())PyErr_SetString(PyExc_ValueError,e.what());return false;}}
bool readVehicleGeometry(PyObject*descriptor,VehicleGeometry&output){try{VehicleGeometry out;auto chassis=p::value(descriptor,"chassis"),hull=p::value(descriptor,"hull"),turret=p::value(descriptor,"turret"),gun=p::value(descriptor,"gun"),hull_mount=p::value(chassis.get(),"hullPosition"),mounts=p::value(hull.get(),"turretPositions"),gun_mount=p::value(turret.get(),"gunPosition");out.chassis=componentBounds(chassis.get());out.hull=componentBounds(hull.get());out.turret=componentBounds(turret.get());out.gun=componentBounds(gun.get());out.hull.offset=nativePoint(hull_mount.get());auto turret_mount=p::item(mounts.get(),0);out.turret_mount=nativePoint(turret_mount.get());for(unsigned i=0;i<3;++i)out.turret_mount[i]+=out.hull.offset[i];out.gun_mount=nativePoint(gun_mount.get());output=std::move(out);return true;}catch(const std::exception&e){if(!PyErr_Occurred())PyErr_SetString(PyExc_ValueError,e.what());return false;}}
bool readLaunchGeometry(PyObject*descriptor,LaunchInput&output){try{auto chassis=p::value(descriptor,"chassis"),hull=p::value(descriptor,"hull"),turret=p::value(descriptor,"turret"),gun=p::value(descriptor,"gun"),hull_mount=p::value(chassis.get(),"hullPosition"),mounts=p::value(hull.get(),"turretPositions");auto ring=p::item(mounts.get(),0);auto result=output;const auto hp=nativePoint(hull_mount.get()),tp=nativePoint(ring.get());for(unsigned i=0;i<3;++i)result.mount[i]=hp[i]+tp[i];const auto turret_geometry=component(turret.get());component(gun.get());result.clearance=std::max(0.,-turret_geometry.bounds.minimum[1]);result.geometry_ready=true;result.exploded_models=true;for(auto*object:{turret.get(),gun.get()}){auto models=p::value(object,"models"),exploded=p::value(models.get(),"exploded");if(exploded.get()==Py_None)result.exploded_models=false;}output=result;return true;}catch(const std::exception&e){if(!PyErr_Occurred())PyErr_SetString(PyExc_ValueError,e.what());return false;}}
bool readPlayerImpulses(PyObject*player,std::vector<PlayerImpulse>&output){try{auto id=p::value(player,"id"),rows=p::value(player,"turret_pushes");return readPlayerImpulses(integer(id.get(),1),rows.get(),output);}catch(const std::exception&e){if(!PyErr_Occurred())PyErr_SetString(PyExc_ValueError,e.what());return false;}}
bool readPlayerImpulses(std::int64_t player,PyObject*rows,std::vector<PlayerImpulse>&output){try{if(player<1||player>2147483647)throw p::Error("Detached turret integer outside wire envelope");const Owner source{true,player};if(!rows||rows==Py_None)return true;auto values=checkpoints(rows);std::vector<PlayerImpulse> out;for(auto&c:values){const auto target=c.player;c.player=source;out.push_back({target,c});}output.insert(output.end(),out.begin(),out.end());return true;}catch(const std::exception&e){if(!PyErr_Occurred())PyErr_SetString(PyExc_ValueError,e.what());return false;}}
PyObject* packRow(const Row&r){try{auto out=p::dict();p::set(out.get(),"actor_kind",p::text(r.owner.human?"player":"bot"));p::set(out.get(),"actor_id",p::integer(r.owner.id));p::set(out.get(),"attitude",p::numbers(r.attitude));p::set(out.get(),"spin",p::numbers(r.spin));p::set(out.get(),"created_time_ms",p::integer(r.created_time_ms));if(r.motion_sequence){p::set(out.get(),"motion_seq",p::integer(r.motion_sequence));p::set(out.get(),"motion_time_ms",p::integer(r.motion_time_ms));p::set(out.get(),"support_key",r.support?p::text(actorKey(*r.support)):p::retain(Py_None));}const auto&f=r.flight;auto flight=p::dict();p::set(flight.get(),"origin",p::numbers(f.origin));p::set(flight.get(),"velocity",p::numbers(f.velocity));p::set(flight.get(),"rest",p::numbers(f.rest));p::set(flight.get(),"impact_velocity",p::numbers(f.impact_velocity));p::set(flight.get(),"duration",p::number(f.duration));p::set(flight.get(),"energy",p::number(f.energy));p::set(flight.get(),"landed",p::boolean(f.landed));p::set(flight.get(),"contact",f.contact?p::numbers(*f.contact):p::retain(Py_None));if(f.rest_attitude)p::set(flight.get(),"rest_attitude",p::numbers(*f.rest_attitude));if(f.body)p::set(flight.get(),"body",packedFrame(*f.body));auto segments=p::list();for(const auto&s:f.segments){auto segment=p::dict();p::set(segment.get(),"origin",p::numbers(s.origin));p::set(segment.get(),"velocity",p::numbers(s.velocity));p::set(segment.get(),"start",p::number(s.start));p::set(segment.get(),"duration",p::number(s.duration));p::append(segments.get(),segment);}p::set(flight.get(),"segments",segments);p::set(out.get(),"flight",flight);return out.release();}catch(const std::exception&e){if(!PyErr_Occurred())PyErr_SetString(PyExc_ValueError,e.what());return nullptr;}}

